// ═══════════════════════════════════════════════════════════════════════════
//  OFIUCO — INTERPRETACIONES
//  Archivo: ofiuco_interpretaciones.js  (JS externo — incluir ANTES del cierre </body>)
//
//  CÓMO FUNCIONA:
//    El módulo Ofiuco busca las interpretaciones en estos objetos globales:
//
//    window.OFIUCO_INTERP_PLANETAS_CASAS  → planeta en casa X
//    window.OFIUCO_INTERP_CASAS           → casa X en signo Y (13 signos)
//    window.OFIUCO_INTERP_ASPECTOS        → planeta A aspecto planeta B
//    window.OFIUCO_INTERP_PARTES          → parte arábiga en signo Y
//    window.OFIUCO_INTERP_ASTEROIDES      → asteroide en signo Y
//
//  FORMATO DE LAS CLAVES:
//    Planetas en casas:  "Sun_casa1", "Moon_casa2", "Mercury_casa3" …
//                         Planetas: Sun Moon Mercury Venus Mars Jupiter
//                                   Saturn Uranus Neptune Pluto NNode SNode
//                                   Chiron Fortuna Vertex Antivertex
//
//    Casas en signos:    "casa1_Aries", "casa1_Tauro" … "casa13_Ofiuco"
//                         Los 13 signos: Aries Tauro Géminis Cáncer Leo Virgo
//                         Libra Escorpio Ofiuco Sagitario Capricornio Acuario Piscis
//
//    Aspectos:           "Sun_con_Moon", "Sun_sex_Mercury", "Moon_cua_Mars"…
//                         Tipos: con sex cua tri opo qui
//
//    Partes arábigas:    "Fortuna_Aries", "Fortuna_Ofiuco" …
//                         Claves de partes: ver TODAS_LAS_PARTES en el JS principal
//
//    Asteroides:         "Ceres_Aries", "Juno_Ofiuco" …
//                         Claves de asteroides: ver TODOS_LOS_ASTEROIDES
//
//  EJEMPLO DE USO:
//    window.OFIUCO_INTERP_PLANETAS_CASAS['Sun_casa1'] =
//      'El Sol en la Primera Casa de Ofiuco potencia la identidad…';
//
// ═══════════════════════════════════════════════════════════════════════════

// ── INICIALIZACIÓN (no borrar) ──────────────────────────────────────────────
window.OFIUCO_INTERP_PLANETAS_CASAS = window.OFIUCO_INTERP_PLANETAS_CASAS || {};
window.OFIUCO_INTERP_CASAS          = window.OFIUCO_INTERP_CASAS          || {};
window.OFIUCO_INTERP_ASPECTOS       = window.OFIUCO_INTERP_ASPECTOS       || {};
window.OFIUCO_INTERP_PARTES         = window.OFIUCO_INTERP_PARTES         || {};
window.OFIUCO_INTERP_ASTEROIDES     = window.OFIUCO_INTERP_ASTEROIDES     || {};


// ═══════════════════════════════════════════════════════════════════════════
// ╔══════════════════════════════════════════════════════════════╗
// ║  1. PLANETAS EN CASAS (zodíaco de 13 casas)                 ║
// ╚══════════════════════════════════════════════════════════════╝
// ═══════════════════════════════════════════════════════════════════════════
/// ── ☉ SOL ──────────────────────────────────────────────────────────────────
window.OFIUCO_INTERP_PLANETAS_CASAS['Sun_casa1']  = `El cambio encarnado — eso es lo que hay aquí. Mientras otros buscan identidad fija, este nativo ya está siendo algo nuevo. El verdadero yo es el que emerge después de cada muerte interna. No lo que se ve en el espejo: lo que sale del otro lado.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Sun_casa2']  = `La mayor riqueza es la capacidad de empezar de cero sin quebrarse. Perder todo varias veces y seguir de pie — ese es el poder real. El dinero llega, pero la verdadera seguridad es saber regenerarse desde la nada.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Sun_casa3']  = `Aquí se dicen cosas que otros apenas piensan. La palabra no es casual: cuando sale, revela. A veces asusta porque nombra verdades que los demás preferían ignorar. Eso no es defecto. Es don.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Sun_casa4']  = `La familia no entiende del todo qué es esta persona. Tal vez nunca lo entienda. Pero en lo profundo, saben que hay algo diferente, algo que no se hereda. Lo que no comprenden es precisamente la fuerza.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Sun_casa5']  = `Lo que se crea no es capricho: es necesidad existencial. Debe salir o sofoca. El arte, los hijos, los proyectos — todos llevan la firma del transformador. Nada de lo que nace aquí viene muerto.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Sun_casa6']  = `El trabajo real no es lo que pagan. Es sanar, estructurar, ordenar caos. Los rotos buscan esta presencia. Las cosas se componen en este entorno — por eso algunos drenan: ven al que puede arreglar lo que ellos desarmaron.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Sun_casa7']  = `Las parejas que llegan vienen a cambiar o a cambiar juntos. Rara vez es fácil. Cada vínculo refleja algo que no se había visto antes. El otro funciona como espejo alquímico.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Sun_casa8']  = `Conocimiento íntimo de la muerte — no por lecturas, sino porque se vivió una, dos, cien veces. Lo que otros temen, aquí se comprende. Eso hace a esta persona peligrosa y necesaria al mismo tiempo.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Sun_casa9']  = `La verdad no viene de libros: se vivió. Por eso cuando se habla de espiritualidad, otros sienten que no es teoría. Es experiencia. Una fe que se compró cara tiene peso que la fe heredada no tiene.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Sun_casa10'] = `El mundo ve a alguien que superó algo enorme. Y es verdad. Esta reputación no es de éxito fácil: es de quien caminó por la oscuridad y salió al otro lado. Eso inspira sin necesidad de esfuerzo.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Sun_casa11'] = `El círculo no es aleatorio. Son los que pasaron por fuego. Esta tribu está hecha de seres que reconocen lo mismo en sí mismos: la capacidad de no quedarse en lo que murió.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Sun_casa12'] = `La soledad no es castigo: es el lugar donde se habla con lo invisible. Ahí, en el silencio, el alma se regenera. Que otros no lo entiendan está bien. Ese espacio es propio.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Sun_casa13'] = `La treceava lección — quien completó el ciclo y descubrió que hay más allá. Consciencia que ya transcendió los doce. El camino es solitario, pero sagrado.`;

// ── ☽ LUNA ─────────────────────────────────────────────────────────────────
window.OFIUCO_INTERP_PLANETAS_CASAS['Moon_casa1']  = `El instinto sabe cosas que la mente no puede explicar. Cuando algo no cierra aunque parezca perfecto en papel, el cuerpo lo rechaza. Esa intuición no es capricho: es oráculo. Vale aprender a confiar en ella.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Moon_casa2']  = `La seguridad real no viene de tener cosas, sino de libertad para transformarse. El dinero solo tranquiliza si compra el derecho a cambiar de rumbo. Estar atrapada es la verdadera pobreza.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Moon_casa3']  = `La mente siente todo. Sensibilidad al subtexto, al tono, a la energía del ambiente. Hablar a veces cansa — porque mientras otros atienden la superficie, aquí se procesa todo lo que no se dice.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Moon_casa4']  = `El hogar importa más de lo que otros creen. No es solo una casa: es el refugio emocional, el único lugar donde se puede bajar la guardia. Sin eso, la estructura interior se desmorona.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Moon_casa5']  = `Cuando se ama, se ama de lleno. La creatividad nace del sentimiento, no de la frialdad. Por eso duele tanto cuando lo amado no valora lo que se puso.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Moon_casa6']  = `La presencia cura sin decir nada. La gente se relaja cerca. El cuerpo tiene medicina. Por eso hay quienes buscan esta energía — y hay que aprender a no vaciarse por darla.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Moon_casa7']  = `Sin seguridad emocional en pareja, no hay vínculo real. La pareja tiene que hablar el lenguaje del corazón, no solo de la razón. El amor necesita ese suelo.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Moon_casa8']  = `Las emociones son océano. A veces ahogan. El trabajo es aprender a nadar en lo profundo sin perder la cabeza — y ese camino pasa por conocer las propias sombras emocionales.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Moon_casa9']  = `La fe es emocional, no intelectual. Se cree en lo que se siente, no en lo que se prueba. La espiritualidad aquí es vivida, orgánica. No necesita demostraciones: necesita experiencias.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Moon_casa10'] = `El mundo percibe accesibilidad, calidez, confianza. Pero por dentro hay necesidades emocionales que rara vez se expresan. Aprender a pedirle también a otros es parte del camino.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Moon_casa11'] = `La amistad es lealtad. Los amigos no son contactos: son familia emocional. La traición duele en lo profundo. Vale buscar gente con quien ser vulnerable sin riesgo.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Moon_casa12'] = `El subconsciente habla en sueños, símbolos, intuiciones. Escucharlo es conocerse. Alta sensibilidad a las emociones colectivas — a veces se carga dolor que no es propio.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Moon_casa13'] = `La memoria emocional es ancestral. Se sienten cosas de vidas pasadas como si fueran propias. Esta emocionalidad es puerta a otros tiempos. No es locura: es conexión.`;

// ── ☿ MERCURIO ─────────────────────────────────────────────────────────────
window.OFIUCO_INTERP_PLANETAS_CASAS['Mercury_casa1']  = `Se ven conexiones que para otros son invisibles. A veces se hablan cosas que aún no están listas para el mundo. Esa inteligencia puede asustar — y eso es señal de que va por buen camino.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mercury_casa2']  = `La palabra vale dinero. Se negocia bien porque se comprende lo no dicho. La gente cree porque se habla desde la certeza, no desde la duda. La riqueza viene de vender ideas, no objetos.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mercury_casa3']  = `Escritor, profesor, orador — el instrumento es la palabra. Pero hay responsabilidad: una palabra que influye debe usarse para revelar, no para controlar.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mercury_casa4']  = `En la familia, este nativo es quien cuestiona. Las preguntas incómodas no buscan problemas: la mente simplemente no puede dejar morir una idea sin resolverla.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mercury_casa5']  = `La creatividad es intelectual. Se escriben conceptos, se inventan sistemas. Sin proyectos que estimulen la mente, viene el tedio — y el tedio es el verdadero enemigo.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mercury_casa6']  = `Talento técnico, buen ojo para los detalles. El riesgo es perderse en lo pequeño y olvidar la imagen grande. El trabajo requiere variedad o se vuelve sofocante.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mercury_casa7']  = `En pareja, la comunicación no es opcional. Sin ella, algo muere lentamente. La pareja ideal puede hablar, discutir, explorar ideas juntos. El silencio prolongado equivale a ruptura.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mercury_casa8']  = `La mente toca lo prohibido. Psicología oscura, sexo, muerte, dinero sucio — no es morbosidad, es curiosidad intelectual sin límites. El pensamiento no se detiene donde otros ponen señales.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mercury_casa9']  = `Se busca la propia verdad, no la que entregan. Se viaja mentalmente por filosofías, religiones, sistemas. La fe necesita sentido lógico para sostenerse.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mercury_casa10'] = `Pensador, consultor, analista — la carrera debe ser de quien resuelve problemas complejos. La reputación es de saber. La mente es el activo principal.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mercury_casa11'] = `Voz del grupo. Hay un rol natural de puente entre facciones. La inteligencia mantiene activo el círculo social.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mercury_casa12'] = `La mente consciente no siempre sabe lo que el inconsciente ya comprendió. Los sueños llegan en código. Aprender a decodificarlos es acceder a otra capa de inteligencia.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mercury_casa13'] = `La mente es puerta interdimensional. El pensamiento ocurre en símbolos. Lo que otros llaman "intuición pura" aquí es análisis.`;

// ── ♀ VENUS ────────────────────────────────────────────────────────────────
window.OFIUCO_INTERP_PLANETAS_CASAS['Venus_casa1']  = `Magnetismo sin esfuerzo. No necesariamente belleza convencional, pero atracción real. Personas, oportunidades, cosas — todas vienen en esta dirección.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Venus_casa2']  = `No se buscan lujos, pero llegan solos. La relación con el dinero es relajada — a veces demasiado. La abundancia existe, pero ignorarla tiene costo.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Venus_casa3']  = `La voz tiene calidez incluso sobre temas duros. La gente quiere escuchar. Hay poder de seducción en las palabras, sin que sea buscado.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Venus_casa4']  = `El hogar necesita belleza o la energía decae. La familia ama profundamente. Hay un rol de centro emocional de la casa.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Venus_casa5']  = `Se ama con generosidad. Las parejas se sienten valoradas. Pero hay un patrón de dar demasiado y olvidar pedir. La creatividad aquí es amorosa y sensual.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Venus_casa6']  = `El servicio es amor. Se cuida con ternura. Pero hay riesgo de volverse esclava de expectativas — hacer tanto que otros dejan de sorprenderse. Aprender a decir no es el trabajo aquí.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Venus_casa7']  = `La pareja importa mucho. A veces demasiado — hasta el punto de sacrificar la propia esencia por mantener la paz. Una pareja verdadera no pide eso.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Venus_casa8']  = `El amor aquí es intenso y transformador. Sin intimidad emocional profunda, no hay sexo real. El cuerpo y el alma van juntos o no van.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Venus_casa9']  = `El amor es universal. Se ama a la humanidad, no solo a una persona. Se lucha por justicia desde el corazón. La fe está puesta en la belleza del mundo.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Venus_casa10'] = `El mundo percibe belleza, accesibilidad, amabilidad. Por dentro hay estándares propios. El carisma facilita la carrera sin que sea la intención.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Venus_casa11'] = `El grupo recibe mucho de esta presencia. Pero hay que asegurarse de que el amor venga de vuelta por lo que se es, no solo por lo que se da.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Venus_casa12'] = `El amor es sacrificio gozoso. Se ama lo invisible: la espiritualidad, el misterio. La devoción puede ser sagrada o puede ser escape. Saber distinguir es la tarea.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Venus_casa13'] = `Cada relación es una iniciación. La pareja enseña algo que no se sabía de uno mismo. La capacidad de amar es el mayor poder de transformación disponible.`;

// ── ♂ MARTE ────────────────────────────────────────────────────────────────
window.OFIUCO_INTERP_PLANETAS_CASAS['Mars_casa1']  = `Fuego interno visible. Otros sienten la intensidad sin que se diga una palabra. No necesariamente agresión — pero hay presencia que domina espacios.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mars_casa2']  = `No se espera que nada llegue solo: se toma. El poder está en la capacidad de acción. El riesgo es confundir querer con necesitar.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mars_casa3']  = `Se discute con pasión. La voz es fuerte. Las palabras pueden herir sin intención. El poder está en defender verdades, no en ganar — esa distinción cambia todo.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mars_casa4']  = `Los propios se defienden con uñas y dientes. Pero la sobreprotección puede volverse control. El fuego debe calentar, no quemar.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mars_casa5']  = `La pasión es creativa, la energía sexual es fuerte. Se necesita alguien que aguante esa intensidad — no que la administre.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mars_casa6']  = `Las oficinas silenciosas no funcionan aquí. Se necesita movimiento, desafío físico. La energía sin canal se vuelve destructiva.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mars_casa7']  = `En pareja: intensidad, pasión, posesividad a veces. La pareja no puede ser pasiva. La competencia es parte del amor aquí.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mars_casa8']  = `El poder sexual es magnético, pero va más allá del sexo: es fusión de almas. La mediocridad no funciona aquí. Se necesitan parejas que puedan con esa profundidad.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mars_casa9']  = `La propia verdad se defiende con fuerza. Hay algo de cruzado en las creencias. El trabajo es distinguir convicción de imposición.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mars_casa10'] = `La carrera requiere lucha. Nada llegó regalado. Pero eso fortaleció. La reputación es de quien no se rinde.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mars_casa11'] = `Los movimientos se lideran desde adentro. La energía moviliza grupos. Pero el liderazgo puede volverse dictatorial si no se trabaja.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mars_casa12'] = `Hay ira subconsciente profunda. A veces las explosiones llegan sin entender de dónde. El trabajo es canalizar esa furia hacia lo sagrado, no hacia lo destructivo.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Mars_casa13'] = `El poder funciona como serpiente: ataca, se retira, espera. No es agresión constante — es estrategia pura. La paciencia combinada con el fuego gana batallas que otros ya dieron por perdidas.`;

// ── ♃ JÚPITER ──────────────────────────────────────────────────────────────
window.OFIUCO_INTERP_PLANETAS_CASAS['Jupiter_casa1']  = `Presencia que hace sentir mejor a quien está cerca. El optimismo es contagioso. Pero a veces es ciego: los peligros también existen y merecen atención.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Jupiter_casa2']  = `El dinero fluye. No siempre riqueza, pero sí capacidad de recuperarse. Las oportunidades de fortuna aparecen. El riesgo es que la abundancia vuelva descuidado.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Jupiter_casa3']  = `Voz de autoridad. Cuando se habla, otros escuchan. Buen comunicador — aunque a veces se habla demasiado o se hacen promesas que no se sostienen.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Jupiter_casa4']  = `El hogar es prosperidad. La familia es bendecida. Pero la casa se vuelve refugio de muchos — y eso tiene un costo de energía.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Jupiter_casa5']  = `La creatividad es expansiva, ambiciosa. El amor por la vida genera cosas. El riesgo es el exceso: demasiado, demasiado rápido.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Jupiter_casa6']  = `Lo que se hace prospera. Hay talento real para casi todo lo que se intenta. La modestia no sale naturalmente — y eso puede generar fricciones.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Jupiter_casa7']  = `La pareja crece al lado de esta persona. El vínculo es expansión. Pero a veces se toma por garantizado. La generosidad en pareja es un regalo, no una obligación.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Jupiter_casa8']  = `Las transformaciones enriquecen. Cada muerte trae más sabiduría. Crisis y evolución son la misma palabra en este lenguaje.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Jupiter_casa9']  = `La fe es la riqueza real. Los viajes son iniciaciones. La visión se expande constantemente. El único riesgo: caer en dogmatismo.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Jupiter_casa10'] = `El destino es expansivo. La carrera crece naturalmente. Pero subir muy rápido sin consolidar bases tiene su propia lección: el orgullo precede la caída.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Jupiter_casa11'] = `La comunidad prospera cerca de esta persona. El optimismo es contagioso. Pero las promesas deben medirse — a veces superan lo que se puede cumplir.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Jupiter_casa12'] = `La conexión con lo divino es natural y profunda. El riesgo es confundir fe con escapismo.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Jupiter_casa13'] = `La expansión es cósmica. No hay límites porque ya se superó el círculo de los doce. La grandiosidad es la bendición y también la maldición.`;

// ── ♄ SATURNO ──────────────────────────────────────────────────────────────
window.OFIUCO_INTERP_PLANETAS_CASAS['Saturn_casa1']  = `Hay peso en esta presencia. Seriedad, reflexión, a veces una madurez que va más allá de la edad. Ese peso es también la fuerza — no hay frivolidad aquí.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Saturn_casa2']  = `La riqueza es lenta pero real. No se especula: se construye. A veces se cargan deudas ajenas o heredadas. Pero lo que se construye, permanece.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Saturn_casa3']  = `Las palabras son medidas. No hay charla vacía. Cuando se habla, importa. Pero la seriedad a veces aísla — la ligereza también tiene su lugar.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Saturn_casa4']  = `La familia fue escuela de dureza. Tal vez dolor, tal vez responsabilidad temprana. Eso endureció de buena manera. El hogar es fortificación, no lujo.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Saturn_casa5']  = `La creatividad requiere disciplina. No hay inspiración pasajera: hay trabajo arduo. Lo que se crea dura porque se construyó con paciencia. La espontaneidad cuesta.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Saturn_casa6']  = `El trabajo es responsabilidad. A veces carga. Pero la confiabilidad es total: si algo se encomienda aquí, se hace. El burnout es real — aprender a soltar es necesario.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Saturn_casa7']  = `La pareja enseña paciencia. Tal vez difícil, tal vez ausente en momentos clave. Pero se aprende amor verdadero: el que dura porque se construye.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Saturn_casa8']  = `Las transformaciones son dolorosas pero profundas. No hay atajos — cada muerte debe vivirse. Lo que emerge al otro lado está purificado.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Saturn_casa9']  = `La fe se prueba continuamente. Solo se cree en lo que se sufrió por creer. La sabiduría viene de años de caminata, no de teoría.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Saturn_casa10'] = `La carrera es lenta pero segura. A los 50 se llega donde a los 25 se quería estar. La vida tarda, pero no falla. La reputación es de confianza.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Saturn_casa11'] = `El grupo necesita a alguien que diga "espera, pensemos bien". Esa seriedad estabiliza. Pero aprender a divertirse con los amigos también es parte del trabajo.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Saturn_casa12'] = `La soledad es donde se forja el alma. Pero sin medida, consume. Se necesita estructura incluso en lo espiritual.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Saturn_casa13'] = `Cada sufrimiento acerca a la verdad. La transformación es lenta porque es profunda. Al final: piedra pulida.`;

// ── ♅ URANO ────────────────────────────────────────────────────────────────
window.OFIUCO_INTERP_PLANETAS_CASAS['Uranus_casa1']  = `Raro, y saberlo. La naturaleza no encaja en categorías. Otros no saben cómo responder. Eso es la fuerza — no se necesita validación convencional.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Uranus_casa2']  = `La relación con el dinero es caótica. Nada, luego fortuna, luego nada. La seguridad no viene de ahorros: viene de saber que siempre sale algo.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Uranus_casa3']  = `La mente salta conexiones imposibles. Las ideas son décadas adelante. Lo que suena a locura hoy es genialidad que el mundo aún no alcanza a ver.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Uranus_casa4']  = `La familia es excéntrica o esta persona lo es para ella. El hogar nunca fue convencional — y eso moldea.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Uranus_casa5']  = `La creatividad es revolucionaria. El arte incomoda, saca a la gente de la zona cómoda. No se busca belleza tradicional: se busca verdad que despierta.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Uranus_casa6']  = `El trabajo debe ser único. La monotonía se rechaza. Hay capacidad de inventar formas nuevas de hacer cosas — pero la estructura tradicional asfixia.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Uranus_casa7']  = `Primero amigo, después amante. Se necesita libertad, no posesión. El matrimonio convencional no funciona aquí. Se busca vínculo que respete la independencia.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Uranus_casa8']  = `La transformación es abrupta. Un día se dice "no más" y todo cambia. El poder está en la capacidad de reinvención instantánea.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Uranus_casa9']  = `La fe es heterodoxa. Se cree en lo que otros llaman locura. La espiritualidad no tiene nombre — es intuición a nivel de genialidad.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Uranus_casa10'] = `La carrera es impredecible. Se llega a lugares inesperados por caminos que nadie trazó. La reputación es de visionario — aunque algunos digan loco.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Uranus_casa11'] = `El grupo es futuro. Mentes raras, geniales. Juntos hacen cosas revolucionarias. La tribu no es convencional.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Uranus_casa12'] = `El inconsciente es eléctrico. Las revelaciones llegan de golpe. Los sueños no son sueños: son avisos.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Uranus_casa13'] = `La transformación es un salto cuántico, no un proceso gradual. Cambio de código genético. La próxima evolución.`;

// ── ♆ NEPTUNO ──────────────────────────────────────────────────────────────
window.OFIUCO_INTERP_PLANETAS_CASAS['Neptune_casa1']  = `Espíritu en cuerpo. A veces no se sabe dónde termina el aura y empieza el mundo. Alta permeabilidad. Otros leen en esta presencia lo que necesitan leer.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Neptune_casa2']  = `La relación con el dinero es mística. A veces hay fe de que llega, otras desaparece sin saber cómo. La materia no es el lenguaje natural aquí.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Neptune_casa3']  = `La palabra es poética. Las metáforas llegan a otros en niveles profundos. Pero a veces hay vaguedad. El lenguaje es musical, no lógico.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Neptune_casa4']  = `El hogar necesita ser hermoso, mágico. La familia tiene secretos no dichos. El pasado es nebuloso — a veces el origen mismo es incierto.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Neptune_casa5']  = `La creatividad es de otro orden. Las obras abren portal a realidades paralelas. Se canaliza, no se inventa. La inspiración es divina.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Neptune_casa6']  = `El servicio es espiritualidad. Se sana por presencia, por fe. Pero hay facilidad para absorber la energía ajena sin protección.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Neptune_casa7']  = `La pareja es sueño o pesadilla — casi siempre idealización. La desilusión llega cuando la realidad no alcanza lo que se imaginó. El trabajo es aprender a amar lo real.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Neptune_casa8']  = `La muerte aquí es disolución suave. No hay resistencia: hay fluir. La sexualidad necesita ser casi sagrada para tener sentido.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Neptune_casa9']  = `La fe es absoluta. No se necesitan pruebas: se necesita vivencia. La espiritualidad es experiencia directa de lo invisible.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Neptune_casa10'] = `La carrera es inspirada. Se hace lo que llama, no lo que se planea. Otros ven un visionario. Pero la indecisión puede hacer perder oportunidades reales.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Neptune_casa11'] = `La comunidad buscada es espiritual. Se quiere tribu mística. El riesgo es caer en grupos que aprovechan la idealización.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Neptune_casa12'] = `El inconsciente es océano infinito. Acceso natural a otros planos. Pero a veces se pierde lo ilusorio de lo real — diferenciarlos es el trabajo de toda la vida.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Neptune_casa13'] = `La transformación es disolución. La identidad desaparece para renacer como pura consciencia. El viaje es espiritual absoluto.`;

// ── ♇ PLUTÓN ──────────────────────────────────────────────────────────────
window.OFIUCO_INTERP_PLANETAS_CASAS['Pluto_casa1']  = `Presencia oscura, magnética, irrefrenable. Otros sienten el poder. Algunos huyen. Otros quedan atrapados. Intentar ser simpático es inútil aquí — no hace falta.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Pluto_casa2']  = `El poder generador es absoluto. La riqueza viene de necesitar el control. Pero cada fortuna requiere la muerte de algo. No es gratis.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Pluto_casa3']  = `La palabra mueve cosas. La tentación de manipular es fuerte. El don es revelar verdades — el riesgo es usarlas como arma.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Pluto_casa4']  = `La familia es la obsesión. Control, enredo en dinámicas de poder. El hogar es fortaleza porque hay algo que proteger.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Pluto_casa5']  = `La creación es obsesiva. Las obras penetran profundo. El sexo transforma a las parejas. Se necesita expresar lo que no puede decirse de otro modo.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Pluto_casa6']  = `El trabajo consume. Obsesión productiva. Hay capacidad de permanecer en lo oscuro mientras se trabaja — algo que pocos pueden hacer.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Pluto_casa7']  = `La pareja sufre transformación profunda o no resiste. Se necesita vínculo que aguante el fuego. El poder sexual regenera o destruye.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Pluto_casa8']  = `Dios del inframundo. La comprensión de la muerte es íntima. Acceso natural a lo prohibido, lo escondido, lo que otros temen tocar.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Pluto_casa9']  = `La verdad aquí penetra. Hace despertar a otros aunque duela. La fe se vive a través del fuego. El camino espiritual requiere muerte de ego.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Pluto_casa10'] = `El poder público es invisible. Se mueve desde la sombra. La carrera maneja lo que otros no pueden ver. La reputación es de alguien que no conviene subestimar.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Pluto_casa11'] = `El grupo experimenta transformación radical. Algunos quedan, otros huyen. Los que se quedan son transformados a nivel celular.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Pluto_casa12'] = `El inconsciente es abismo. Acceso a memorias ancestrales, a lo que la humanidad enterró. La psiquis toca el lado oscuro de la existencia.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Pluto_casa13'] = `Alquimista absoluto. La transformación es total, sin vuelta atrás. Cada muerte acerca más a la verdad que yace en el fondo del universo.`;

// ── ⚸ QUIRÓN ──────────────────────────────────────────────────────────────
window.OFIUCO_INTERP_PLANETAS_CASAS['Chiron_casa1']  = `La herida es visible. A veces hay un cojear por dentro. Pero precisamente eso que duele es lo que convierte en experto. La debilidad es la enseñanza.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Chiron_casa2']  = `El valor viene de la pérdida. Tal vez dinero, seguridad, familia. Pero se aprendió a recuperarse. Ahora se puede enseñar a otros que el dinero no es el final.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Chiron_casa3']  = `La palabra sana porque viene de cicatriz. Se habla desde lo roto. Otros se sienten comprendidos porque aquí no se disfrazan los dolores. La comunicación es terapia.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Chiron_casa4']  = `La familia hirió. Tal vez negligencia, tal vez violencia. Pero se decidió romper el ciclo. Lo que no se recibió ahora se da a otros — hijos biológicos o espirituales.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Chiron_casa5']  = `La creatividad emerge del dolor. Las obras hablan de lo que se sufrió. Lo que era herida ahora es arte. El sufrimiento se convierte en belleza.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Chiron_casa6']  = `La profesión es sanar. Terapeuta, médico, chamán. Especialista en lo incurable. La propia herida enseña a tocar a otros sin juzgar.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Chiron_casa7']  = `La pareja sana a través de este vínculo. A veces se sufre juntos antes de que el amor cure. El riesgo es confundir rescatar con amar.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Chiron_casa8']  = `Las transformaciones enseñan. El sexo debe sanar o no tiene sentido. El poder está en lo profundo.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Chiron_casa9']  = `La sabiduría viene del sufrimiento, no de los libros. Se enseña que la fe debe probarse en el fuego. Maestría de herida procesada.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Chiron_casa10'] = `La carrera es curación. Se contrata a esta persona porque tiene empatía de quien pasó. La reputación es de entender porque se vivió.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Chiron_casa11'] = `La comunidad sana junto a esta presencia. Se puede decir "entiendo porque viví eso" — y eso vale más que cualquier teoría. Atrae a otros heridos.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Chiron_casa12'] = `La herida espiritual es la clave de la evolución. Tal vez duda de fe, tal vez desconexión divina. Buscar esa reconexión es el camino sagrado.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['Chiron_casa13'] = `La sanación es iniciática. Se caminó por el infierno y se volvió. Ahora se puede guiar a otros por caminos oscuros porque ya se estuvo ahí. La mayor herida procesada es el mayor poder.`;

// ── ☊ NODO NORTE ──────────────────────────────────────────────────────────
window.OFIUCO_INTERP_PLANETAS_CASAS['NNode_casa1']  = `Tu destino es volverse visible y real en el mundo. Dejas de esconderte detrás de máscaras para mostrarte tal como eres. La presencia auténtica es lo que construye tu autoridad. Aprender a ocupar espacio sin pedir permiso es tu tarea fundamental.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['NNode_casa2']  = `Necesitas crear valor desde tu propio mérito, no desde lo que heredas. Tu verdadera riqueza viene de saber qué tienes adentro, no afuera. Construir autoestima basada en logros reales es lo que te falta. El dinero y los recursos llegan cuando dejas de tener miedo de lo que mereces.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['NNode_casa3']  = `Tu misión es aprender a hablar con tu propia voz, no la de otros. Escuchar antes de juzgar te enseña más de lo que crees. Tu inteligencia se desarrolla saliendo de la ignorancia elegida. Comunicar lo que realmente piensas es más valiente de lo que parece.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['NNode_casa4']  = `Necesitas crear un hogar que sea tuyo, no heredado ni controlado. Establecer raíces emocionales sólidas es lo que te falta para crecer. Tu seguridad interna debe venir de ti, no de la familia. Soltar lo familiar para construir lo propio es tu aprendizaje.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['NNode_casa5']  = `Tu destino es crear sin medir el resultado ni esperar validación. Expresarte libremente, aunque sea "feo" o incómodo, es donde crece tu poder. El juego, el gozo y el riesgo creativo son tus medicinas. Aprender a jugar en serio sin controlar todo es tu lección.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['NNode_casa6']  = `Servir debe ser una elección consciente, no una obligación heredada. Tu cuerpo necesita atención y cuidado real, no automático. Trabajar en algo que tiene sentido para ti cambia todo tu sistema. Disciplina en lo pequeño construye libertad en lo grande.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['NNode_casa7']  = `Aprender del otro sin perder quién eres es tu desafío. Necesitas relaciones que te enseñen sobre ti, no que te definan. La asociación real viene cuando ambos están completos. Tu pareja no es tu salvación sino tu espejo.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['NNode_casa8']  = `Descender a lo profundo y quedarte ahí es lo que te falta. Tu poder real viene de transformar lo que tienes miedo de tocar. Intimidad verdadera requiere que bajes las defensas. Dominar lo oculto te convierte en alguien que otros respetan sin saber por qué.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['NNode_casa9']  = `Tu fe debe ser propia, no heredada de otros ni de libros. Viajar, explorar ideas radicales es donde crecen tus alas. Cuestionar lo que "siempre fue así" es tu permiso. Encontrar tu verdad personal es el norte que nunca termina.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['NNode_casa10'] = `El mundo espera que ocupes un lugar público específico. Tu autoridad viene de saber quién eres, no de qué dices que eres. Responsabilidad y visibilidad son dos caras de la misma moneda. Crear un legado que trascienda es tu destino, no tu opción.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['NNode_casa11'] = `Pertenecemos a algo más grande que nosotros mismos es tu aprendizaje. Tu tribu no es la que te nació sino la que eliges conscientemente. Contribuir a causas que importan te da significado profundo. Soledad desaparece cuando actúas por la humanidad, no por ti.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['NNode_casa12'] = `Conectar con lo invisible, lo espiritual, es lo que sana tu alma. Tu poder crece cuando sueltas el control y confías. Servir sin esperar retorno te enseña la verdadera generosidad. Disolver el ego en algo mayor que ti es tu liberación.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['NNode_casa13'] = `La gran transformación requiere que regreses a tu origen renovado. Cada ciclo te trae más consciencia si lo aprovechas. Integrar todo lo aprendido en una versión mejorada de ti es el propósito. Renacer sin perder lo esencial es tu verdadero poder.`;

// ── ☋ NODO SUR ──────────────────────────────────────────────────────────
window.OFIUCO_INTERP_PLANETAS_CASAS['SNode_casa1']  = `Tienes la tendencia a dominar habitaciones sin saber si es necesario. Tu poder es tan fuerte que otros se achican, pero eso no es liderazgo. Soltar la necesidad de ser el centro es lo primero. Aprender que tu presencia cansa a otros si no sabes modularla.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['SNode_casa2']  = `Crees que la seguridad viene de tener cosas, de acumular sin fin. Sueltas dinero y recursos pero aprendes a soltar la ansiedad sobre ellos. Tu miedo a la pobreza es más real que la pobreza. Confiar en tu capacidad de generar es tu verdadera riqueza.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['SNode_casa3']  = `Hablas más de lo que escuchas, opinas sin conocer realmente. Tu mente está llena de información pero vacía de sabiduría. Soltar la certeza de que tienes razón te abre a aprender. Callarte es más fuerte que defenderte verbalmente.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['SNode_casa4']  = `La familia es tu cárcel disfrazada de seguridad. Vuelves a lo familiar porque es lo único que conoces. Soltar la lealtad ciega a la tribu es doloroso pero necesario. Tu identidad debe ser propia, no heredada.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['SNode_casa5']  = `Tu creatividad es para el ego, no para expresar el alma. Necesitas validación y reconocimiento o no creas. Soltar la necesidad de ser visto es lo más difícil. Crear en silencio sin esperar aplauso es donde encontrás tu verdadero gozo.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['SNode_casa6']  = `Servir es tu patrón porque no sabes decir que no. Tu cuerpo carga el estrés de aceptar todo sin límite. Soltar la culpa cuando otros se decepcionan es urgente. Aprender que decir "no" es un acto de amor, no de egoísmo.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['SNode_casa7']  = `Dependes de otros para saber quién eres realmente. Sin pareja o asociado, te disuelves en inseguridad. Soltar la creencia de que necesitas a alguien para existir es tu lección. Tu autonomía debe ser el cimiento, no la pareja.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['SNode_casa8']  = `Controlas lo profundo con rigidez porque tienes miedo de perder. Tu intimidad es una transacción, no una entrega real. Soltar el control es soltar la ilusión de seguridad. Rendirte emocionalmente revela una fuerza que no sabías que tenías.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['SNode_casa9']  = `Tu fe es prestada, la de tu religión, tu cultura, tu tribu. Crees porque otros creen, no porque lo hayas cuestionado. Soltar el dogma duele pero te libera. Tu verdad propia es lo único que te sostiene cuando todo se cae.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['SNode_casa10'] = `Tu estatus social importa más de lo que admites. Buscas autoridad externa para sentirte completo. Soltar el título y la posición te revela quién realmente eres. Tu valor no depende del cargo que ocupas.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['SNode_casa11'] = `Te pierdes en lo colectivo, en las ideologías de grupo. Tu opinión individual desaparece bajo el peso de la mayoría. Soltar la necesidad de pertenecer es traición, pero es liberación. Tu voz personal importa más que estar "con los correctos".`;

window.OFIUCO_INTERP_PLANETAS_CASAS['SNode_casa12'] = `Escapas cuando la realidad duele, te pierdes en fantasía o sustancias. Tu conexión con lo espiritual es desencarnada, no presente. Soltar el escapismo es enfrentar un mundo que no quieres ver. Encarnar el espíritu en lo cotidiano es tu verdadera prueba.`;

window.OFIUCO_INTERP_PLANETAS_CASAS['SNode_casa13'] = `Has transformado sin consciencia, dejando cicatrices por donde pasas. Tu poder de cambio es destructivo porque no integras. Soltar el caos del cambio por el cambio es lo primero. Transformarse con propósito claro es lo que te libera de repetir patrones.`;


