const _OPH_PARTES_COMUNES = ['Fortuna','Espiritu','Amor','Matrimonio','Hijos',
  'Enfermedad','Trabajo','Amigos','Enemigos','Viajes','Muerte','Herencia'];

_OPH_PARTES_COMUNES.forEach(parte => {
  _OPH_SIGNOS_13.forEach(signo => {
    const clave = `${parte}_${signo}`;
    window.OFIUCO_INTERP_PARTES[clave] = window.OFIUCO_INTERP_PARTES[clave] || ``;
  });
});

